p = "data/producers.json"
d = json.loads(open(p, "r", encoding="utf-8", newline="").read())
for key, langs in BLURBS.items():
    for lg, text in langs.items():
        d["producers"][key]["blurb"][lg] = text
    print("%-14s %d languages, hr %3d chars" % (key, len(langs), len(langs["hr"])))
for key, subs in FIX.items():
    for lg, t in d["producers"][key]["blurb"].items():
        for a, b in subs:
            if a in t: d["producers"][key]["blurb"][lg] = t.replace(a, b); print(f"  {key} [{lg}]: {a} -> {b}")
open(p, "w", encoding="utf-8", newline="").write((json.dumps(d, ensure_ascii=False, indent=1) + "\n").replace("\n", "\r\n"))

p = "library/wines.json"
w = json.loads(open(p, "r", encoding="utf-8", newline="").read())
for ref, langs in NOTE.items():
    w["wines"][ref]["note"] = langs
    print("note rewritten:", ref)
open(p, "w", encoding="utf-8", newline="").write((json.dumps(w, ensure_ascii=False, indent=1) + "\n").replace("\n", "\r\n"))
print("written")
